style.css:
@-moz-document regexp("https?://(www\.)?google\.(com|co\.uk)/($|\?.*|webhp.*|search\?.*tbm=.*)") {
/* ---------- Tokens ---------- */
  :root {
    --m-bg: #000;
    --m-ink: #d9d9d9;
    --m-text: #bdbdbd;
    --m-muted: #6f6f6f;
    --m-line: #262626;
    --m-font: "Inter Tight", "Helvetica Neue", Arial, sans-serif;
  }

  /* ---------- Base ---------- */
  html, body {
    background: var(--m-bg) !important;
    color: var(--m-text) !important;
    font-family: var(--m-font) !important;
    font-size: 11px !important;
    -webkit-font-smoothing: antialiased;
  }

  a, a:visited { color: var(--m-text) !important; text-decoration: none !important; }
  a:hover { color: #fff !important; text-decoration: underline !important; text-underline-offset: 3px; }

  /* ---------- Top bar ---------- */
  #gb, header, #gb > div {
    background: transparent !important;
    border-bottom: 1px solid var(--m-line) !important;
    box-shadow: none !important;
  }

  /* Gmail / Images links: sentence case, small, no tracking */
  #gb a, header a {
    text-transform: none !important;
    letter-spacing: 0 !important;
    font-size: 11px !important;
  }

  /* ---------- Logo ---------- */
  img.lnXdpd {
    width: clamp(220px, 40vw, 520px) !important;
    height: auto !important;
    max-height: none !important;
    filter: grayscale(1) brightness(0.85);   /* light grey like the example */
    margin-bottom: 40px !important;
  }

  /* ---------- Search bar: pill -> hairline underline ---------- */
  .RNNXgb,
  form[role="search"] > div > div:first-child {
    background: transparent !important;
    border: 0 !important;
    border-bottom: 1px solid var(--m-ink) !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    max-width: 640px !important;
    transition: border-color 0.2s;
  }

  .RNNXgb:focus-within { border-bottom-color: #fff !important; }

  textarea[name="q"], input[name="q"] {
    background: transparent !important;
    color: var(--m-ink) !important;
    font-family: var(--m-font) !important;
    font-size: 16px !important;
    caret-color: #fff;
  }

  /* Hide the dark inner box and the extra icons/AI mode pill */
  .a4bIc, .SDkEP, .vOY7J, .XDyW0e, .nDcEnd, .Gdd5U {
    background: transparent !important;
    border-radius: 0 !important;
  }

  /* ---------- Buttons: boxes -> underlined text ---------- */
  .FPdoLc input, .lJ9FBc input, input.gNO89b, input.RNmpXc {
    background: transparent !important;
    border: 0 !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    color: var(--m-text) !important;
    font-family: var(--m-font) !important;
    font-size: 11px !important;
    letter-spacing: 0 !important;
    text-transform: none !important;
    text-decoration: underline;
    text-decoration-color: var(--m-muted);
    text-underline-offset: 3px;
    padding: 0 10px !important;
    height: auto !important;
    min-width: 0 !important;
  }

  .FPdoLc input:hover, .lJ9FBc input:hover {
    color: #fff !important;
    text-decoration-color: #fff;
  }

  /* ---------- Footer ---------- */
  .KxwPGc, #fbar, .fbar, #SIvCob {
    background: transparent !important;
    border-top: 1px solid var(--m-line) !important;
    color: var(--m-muted) !important;
    font-size: 11px !important;
  }

  /* Country row sits on its own hairline, not a grey block */
  .uU7dJb, .Q8LRLc {
    background: transparent !important;
    color: var(--m-muted) !important;
    border-bottom: 1px solid var(--m-line) !important;
  }

  /* ---------- Misc cleanup ---------- */
  *::-webkit-scrollbar { width: 6px; height: 6px; }
  *::-webkit-scrollbar-thumb { background: var(--m-line); }
  *::-webkit-scrollbar-track { background: transparent; }
}
